-- The Color Block look went live for everyone (Sean, 2026-11-11: "I'm ready for it to go live"). Canon status update.
update knowledge_records set body = coalesce(body,'{}'::jsonb) || jsonb_build_object('status','LIVE','live_since','2026-11-11','go_live_quote','I''m ready for it to go live.','how','public/ve-look.js from nav.js on every page adds html.ve-cb and loads public/ve-look.css; page rules go there under html.ve-cb; ?look=off per browser for checks. Homepage index.html, Directory doors directory/index.html, hubs ve-look-hubs.css, house ads ads/ on the kit template.'), updated_at = now() where slug = 'canon-ve-look-color-block';
